def execute_booking(agent, request):

    try:
        result = search_hotels(request)

        if not result.get("hotels"):
            return {
                "status": "needs_input",
                "message": "No available hotels found."
            }

        return {
            "status": "completed",
            "data": result
        }

    except ValueError as error:
        return {
            "status": "needs_input",
            "message": str(error)
        }

    except Exception:
        return {
            "status": "failed",
            "message": "Booking service unavailable."
        }

